/**
 * Corrections to Clalit's own clinic coordinates.
 *
 * `clinic-directory.ts` is a faithful import of `nearme.clalit.co.il/c.json` and must stay that way - it
 * is regenerated by `pnpm clinics:fetch`. But a few of Clalit's own points are wrong, and a wrong point
 * is not a harmless one: it is the distance the row shows, so it reads as OUR arithmetic being broken.
 *
 * Each entry here is a branch whose published point contradicts its published ADDRESS, with the source
 * of the replacement and the size of the error. Keep it tiny, keep every entry sourced, and drop an
 * entry the moment Clalit fixes it upstream (docs §14).
 */

import type { LatLng } from "@/lib/geo";

import { DENTAL_CLINIC_COORDS } from "./clinic-directory";

const CLINIC_COORD_FIXES: Record<string, LatLng> = {
  /**
   * כללית סמייל - אוניברסיטת תל אביב. Clalit publishes [32.066236, 34.7789339], which is central Tel
   * Aviv - 6.0 km from the address the same record carries ("ביה"ס לרפואת שיניים בקמפוס האוניברסיטה,
   * הגישה דרך שער 10"). Replacement is OpenStreetMap's own node for that school (queried 2026-08-15:
   * nominatim `Goldschleger School of Dental Medicine Tel Aviv University`).
   */
  865193: [32.117326, 34.804497]
};

/** A clinic's position by nav code - Clalit's, unless one of its points is known to be wrong. */
export function clinicCoords(navCode: string): LatLng | undefined {
  return CLINIC_COORD_FIXES[navCode] ?? DENTAL_CLINIC_COORDS[navCode];
}
